gMA(){return"\u0986\u09aa\u09a8\u09be\u09b0 \u09b9\u09be\u09a4\u09c7 \u09a5\u09be\u0995\u09be \u09a8\u0997\u09a6, \u0996\u09b0\u099a, \u098f\u09ac\u0982 \u09b9\u09b8\u09cd\u09a4\u09be\u09a8\u09cd\u09a4\u09b0"},
gMN(){return"\u0985\u09b0\u09cd\u09a5\u09ac\u099b\u09b0"},
gMM(){return"\u098f\u0995\u099f\u09bf \u09ac\u099b\u09b0\u09c7\u09b0 \u09b9\u09bf\u09b8\u09be\u09ac \u09ac\u09a8\u09cd\u09a7 \u09ac\u09be \u09aa\u09c1\u09a8\u09b0\u09be\u09af\u09bc \u0996\u09c1\u09b2\u09c1\u09a8"},
gML(){return"\u0996\u09b0\u099a\u09c7\u09b0 \u09ac\u09bf\u09ad\u09be\u0997"},
gMK(){return"\u09b8\u09ae\u09cd\u09aa\u09be\u09a6\u09a8\u09be\u09af\u09cb\u0997\u09cd\u09af, \u09a6\u09b2\u09ac\u09a6\u09cd\u09a7\u09af\u09cb\u0997\u09cd\u09af \u2014 \u09af\u09c7\u09ae\u09a8 \u09af\u09be\u09a8\u09ac\u09be\u09b9\u09a8 \u0996\u09b0\u099a > \u09af\u09be\u09a8\u09ac\u09be\u09b9\u09a8 \u09e7 > \u09aa\u09c7\u099f\u09cd\u09b0\u09cb\u09b2"},
