gT2(){return"\u09b8\u09c1\u0987\u09ab\u099f \u0995\u09cb\u09a1"},
gST(){return"\u09ab\u09be\u0993\u09b0\u09be\u09a8 \u09ac\u09bf\u09ac\u09b0\u09a3 (\u0990\u099a\u09cd\u099b\u09bf\u0995)"},
gSS(){return"\u09a4\u09be\u09ce\u0995\u09cd\u09b7\u09a3\u09bf\u0995 \u09b8\u09cd\u09a5\u09be\u09a8\u09be\u09a8\u09cd\u09a4\u09b0\u09c7\u09b0 \u099c\u09a8\u09cd\u09af \u0986\u09aa\u09a8\u09be\u09b0 \u09ab\u09be\u0993\u09b0\u09be\u09a8 \u0986\u0987\u09a1\u09bf / QR \u09b0\u09c7\u09ab\u09be\u09b0\u09c7\u09a8\u09cd\u09b8"},
gSP(){return"\u09a8\u09a5\u09bf\u09b0 \u09ab\u09a8\u09cd\u099f"},
gGP(){return"\u09a8\u09a5\u09bf\u09b0 \u0989\u099a\u09cd\u099a\u09be\u09b0\u09a3 \u09b0\u0999"},
gGR(){return"\u099f\u09cd\u09af\u09be\u0997\u09b2\u09be\u0987\u09a8 \u09b0\u0999"},
gT4(){return"\u09aa\u09cd\u09b0\u09a4\u09bf\u099f\u09bf \u09a8\u09a5\u09bf\u09a4\u09c7 \u0986\u09aa\u09a8\u09be\u09b0 \u09a8\u09be\u09ae\u09c7\u09b0 \u09a8\u09bf\u099a\u09c7 \u09ae\u09c1\u09a6\u09cd\u09b0\u09bf\u09a4"},
gT3(){return"\u0986\u09aa\u09a8\u09be\u09b0 \u09ae\u09c1\u09a6\u09cd\u09b0\u09bf\u09a4 \u09a8\u09a5\u09bf\u09a4\u09c7 \u09aa\u09cd\u09b0\u09a4\u09bf\u099f\u09bf \u099f\u09c7\u09ac\u09bf\u09b2/\u09ac\u0995\u09cd\u09b8 \u09ac\u09b0\u09cd\u09a1\u09be\u09b0\u09c7\u09b0 \u099c\u09a8\u09cd\u09af\u0993 \u09ac\u09cd\u09af\u09ac\u09b9\u09c3\u09a4 \u09b9\u09af\u09bc \u2014 \u09aa\u09cd\u09b0\u09bf\u09a8\u09cd\u099f \u09b2\u09c7\u0986\u0989\u099f \u09a8\u09bf\u099c\u09c7\u0987 \u0995\u0996\u09a8\u0993 \u09aa\u09b0\u09bf\u09ac\u09b0\u09cd\u09a4\u09a8 \u09b9\u09af\u09bc \u09a8\u09be, \u09b6\u09c1\u09a7\u09c1 \u098f\u0987 \u098f\u0995\u099f\u09bf \u09b0\u0999\u0964"},
